def merge_tool_results(calls, results):
    seen = set()
    for call in calls:
        cid = call['id']
        if cid in seen:
            raise ValueError('duplicate call id: %r' % (cid,))
        seen.add(cid)

    by_id = {}
    for result in results:
        by_id[result['id']] = result

    out = []
    for call in calls:
        cid = call['id']
        result = by_id.get(cid)
        if result is None:
            out.append({'id': cid, 'status': 'pending'})
        else:
            out.append({
                'id': cid,
                'status': 'done',
                'content': result.get('content', ''),
            })
    return out

