def summarize_usage(events):
    totals = {}
    for event in events:
        request_id = event['request_id']
        inp = event.get('input', 0)
        out = event.get('output', 0)
        if inp < 0 or out < 0:
            raise ValueError('token counts must be nonnegative')
        bucket = totals.setdefault(request_id, [0, 0])
        if inp > bucket[0]:
            bucket[0] = inp
        if out > bucket[1]:
            bucket[1] = out
    return {'input': sum(b[0] for b in totals.values()),
            'output': sum(b[1] for b in totals.values())}

