def summarize_usage(events):
    totals = {}
    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)
        if input_count < 0 or output_count < 0:
            raise ValueError('token counts must be nonnegative')
        if request_id not in totals:
            totals[request_id] = {'input': 0, 'output': 0}
        totals[request_id]['input'] = max(totals[request_id]['input'], input_count)
        totals[request_id]['output'] = max(totals[request_id]['output'], output_count)
    return {
        'input': sum(t['input'] for t in totals.values()),
        'output': sum(t['output'] for t in totals.values()),
    }

