def summarize_usage(events):
    totals = {'input': 0, 'output': 0}
    per_request = {}
    for event in events:
        request_id = event['request_id']
        counts = {}
        for key in ('input', 'output'):
            value = event.get(key, 0)
            if value < 0:
                raise ValueError(f"negative {key} count: {value}")
            counts[key] = value
        if request_id not in per_request:
            per_request[request_id] = counts
        else:
            for key in ('input', 'output'):
                per_request[request_id][key] = max(per_request[request_id][key], counts[key])
    for counts in per_request.values():
        totals['input'] += counts['input']
        totals['output'] += counts['output']
    return totals

